<template>
	<view class="container">
		<u-loading-page :loading="true" v-if="load" fontSize="28rpx" />
		<block v-else>
		<scroll-view scroll-y="true" class="scroll">
			<view class="cart-container">
				<view class="confirm-address order-group" @click="toAddress">
					<image src="@/static/common/dingwei.png" mode="widthFix" class="icon-img"/>
					<view class="confirm-address-right" v-if="Object.keys(user_address).length>0">
						<view class="confirm-address-consignee">
							<text class="consignee-text">{{user_address.consignee}}</text>
							<text class="mobile-text">{{user_address.mobile}}</text>
						</view>
						<text class="detail-text">{{user_address.province+user_address.city+user_address.district+user_address.address}}</text>
					</view>
					<view class="confirm-address-add" v-else>添加收货地址</view>
					<u-icon name="arrow-right" color="#353535" size="16" class="arrow-right" />
				</view>
				<view class="goods-items order-group">
					<view class="goods-item">
						<image :src="goods.goods_img" class="goods-img" mode="aspectFit"/>
						<view class="goods-item-right">
							<view class="goods-name">{{goods.goods_name}}</view>
							<view class="goods-bot-box">
								<view class="goods-price">
									<text>¥</text>
									<text class="jiage">{{goods.goods_price}}</text>
								</view>
								<view class="goods-num-box">x{{goods.goods_num}}</view>
								<view class="goods-num-box" v-if="false">
									<text :class="{'dis':goods.goods_num<=1}"
										@click="changeNum(goods,-1)">-</text>
									<text class="number">{{goods.goods_num}}</text>
									<text :class="{'dis':goods.goods_num>=goods.max}"
										@click="changeNum(goods,1)">+</text>
								</view>
							</view>
						</view>
					</view>
					<view class="note-row">
						<text>用户备注</text>
						<u-input border="none"  placeholder="请输入用户备注(选填)"
							placeholderClass="placeholder28" type="text" fontSize="28rpx" clearable v-model="user_note" />
					</view>
				</view>
				<view class="order-rows order-group">
					<view class="order-row">
						<text>订单总额</text>
						<text>¥{{total_amount}}</text>
					</view>
					<view class="order-row">
						<view class="left">
							<text>使用积分</text>
							<text class="grey small">(可用{{user.jifen}})</text>
						</view>
						<text>¥{{goods.jifen * goods.goods_num}}</text>
					</view>
					<view class="order-row">
						<view class="left">
							<text>使用金豆</text>
							<text class="grey small">(可用{{user.jindou}})</text>
						</view>
						<text>¥{{goods.cash * goods.goods_num}}</text>
					</view>
					<view class="order-row">
						<text>运费</text>
						<text>¥{{goods.freight}}</text>
					</view>
				</view>
				<view class="pay-container order-group" v-if="pay_list.length>0">
					<view class="title">请选择支付方式</view>
					<view class="pay-rows">
						<view class="pay-row" v-for="(item,index) in pay_list" :key="index" @click="changePay(item)">
							<image :src="item.pay_img" mode="widthFix" class="zf-img"/>
							<text>{{item.pay_name}}</text>
							<image 
							:src="item.pay_code==pay_code?'/static/common/checkbox_select.png':'/static/common/checkbox_unselect.png'"
							 mode="widthFix" 
							 class="icon-img"/>
						</view>
					</view>
				</view>
				<view style="height: 20rpx;"></view>
			</view>
		</scroll-view>
		<view class="cart-bottom" v-if="Object.keys(goods).length>0">
			<view class="center">合计</view>
			<view class="amount">
				<text>¥</text>
				<text class="total-amount">{{total_amount}}</text>
			</view>
			<button class="submit-btn" @click="cart_tj(2)" :disabled="submitDisabled">立即支付</button>
		</view>
		</block>
	</view>
</template>

<script>
	var _this;
	export default {
		data() {
			return {
				goods_id: 0,
				goods_num: 0,
				user_note: '',
				submitDisabled:false,
				goods:{},
				user_address:{},
				pay_list:[],
				pay_code:'',
				user:{}
			};
		},
		methods: {
			async cart_tj(step = 1){
				const params = {
					goods_id: _this.goods_id,
					goods_num: _this.goods_num,
					step: step,
				}
				// #ifdef MP-WEIXIN
				let openid = uni.getStorageSync('unionid')?uni.getStorageSync('unionid'):uni.getStorageSync('openid')
				params.is_xcx = 1
				params.openid = openid
				// #endif
				if(_this.action){
					params.action = _this.action
				}
				if (step == 2) {
					params.pay_code = _this.pay_code
					params.user_note = _this.user_note
					params.address_id = _this.user_address?.address_id || 0
					let goods = {
						goods_id:_this.goods_id,
						goods_num:_this.goods.goods_num,
					}
					params.goods = goods
					_this.submitDisabled = true
					setTimeout(()=>{
						_this.submitDisabled = false
					},2000)
				}
				const data = await _this.$post('port/add_jf_order', params)
				if (data.code == -1) {
					_this.user_address = data.result.add || {}
					_this.goods = data.result.goods
					_this.pay_list = data.result.pay_list
					if (_this.pay_list.length>0) {
						_this.pay_code = _this.pay_list[0]['pay_code']
					}
					_this.user = data.result.user
					if (_this.load) {
						_this.load = false
					}
				}else if(data.code==50){
					if(_this.pay_code == 'alipayMobile'){
						// location.href = data.result.url
						location.replace(data.result.url)
						// _this.finish()
					}else if (_this.pay_code == 'weixinH5') {
						location.href = data.result.url
						uni.showModal({
							title:'提示',
							content:'请确认是否已完成支付',
							confirmText:'已完成支付',
							cancelText:'未完成支付',
							success(res) {
								_this.queryOrder(data.result.order_sn)
							}
						})
					}else{
						let wx_result = data.result.wx_result
						function onBridgeReady(){
						   WeixinJSBridge.invoke(
						      'getBrandWCPayRequest', wx_result,
						      function(res){
								  if(res.err_msg == "get_brand_wcpay_request:ok" ){
										// 使用以上方式判断前端返回,微信团队郑重提示：
										//res.err_msg将在用户支付成功后返回ok，但并不保证它绝对可靠。
										uni.$u.toast('支付成功',()=>{
											_this.toNext(`/pages/order/jf-order-list?type=2`,true)
										})
								  }else if (res.err_msg=="get_brand_wcpay_request:cancel") {
										uni.$u.toast('支付过程中用户取消',()=>{
											_this.toNext(`/pages/order/jf-order-list?type=1`,true)
										})
								  }else{
									  uni.$u.toast('支付失败',()=>{
											_this.toNext(`/pages/order/jf-order-list?type=1`,true)
										})
								  }
						   }); 
						}
						if (typeof WeixinJSBridge == "undefined"){
						   if( document.addEventListener ){
						       document.addEventListener('WeixinJSBridgeReady', onBridgeReady, false);
						   }else if (document.attachEvent){
						       document.attachEvent('WeixinJSBridgeReady', onBridgeReady); 
						       document.attachEvent('onWeixinJSBridgeReady', onBridgeReady);
						   }
						}else{
						   onBridgeReady();
						}
					}
				}else if(data.code==-50){
					console.log(data);
					uni.requestPayment({
						provider: 'wxpay',
						timeStamp: data.result.timeStamp+'',
						nonceStr: data.result.nonceStr,
						package: data.result.package,
						signType: data.result.signType,
						paySign: data.result.sign,
						success(res) {
							console.log('success:' + JSON.stringify(res));
							_this.$u.toast('支付成功',()=>{
								_this.toNext('/pages/order/jf-order-list?type=2',true)
							})
						},
						fail(err) {
							_this.$u.toast('支付失败',()=>{
								_this.toNext('/pages/order/jf-order-list?type=1',true)
							})
							console.log('fail:' + JSON.stringify(err));
						}
					});
				}else if(data.code==20){
					uni.$u.toast(data.msg,()=>{
						_this.finish()
					})
				}else if(data.code==10){
					uni.$u.toast(data.msg,()=>{
						_this.toNext(`/pages/order/jf-order-list?type=0`,true)
					})
				}else {
					uni.$u.toast(data.msg)
				}
			},
			//查询订单支付状态
			async queryOrder(order_sn){
				let params = {
					order_sn
				}
				const data = await _this.$post('port/chaxun_order', params)
				if (data.code==200) {
					_this.toNext(`/pages/order/jf-order-list?type=2`,true)
				} else if(data.code==100){
					_this.toNext(`/pages/order/jf-order-list?type=1`,true)
				}else{
					uni.$u.toast(data.msg,()=>{
						_this.finish()
					})
				}
			},
			changeNum(item, step) {
				var number = item.goods_num + step
				if (step < 0) {
					if (number < 1) {
						return
					}
					item.goods_num = number
				} else {
					if (number > item.max) {
						return;
					}
					item.goods_num = number
				}
			},
			toAddress(){
				_this.toNext(`/pages/my/address-list?is_cart=1`)
			},
			changePay(item){
				if (item.pay_code == _this.pay_code) {
					return
				}
				_this.pay_code = item.pay_code
			},
		},
		onLoad(e) {
			_this = this;
			if (e) {
				for (let item in e) {
					_this[item] = e[item]
				}
			}
			_this.cart_tj()
			uni.$on('chooseAddress',res=>{
				_this.user_address = res
			})
		},
		onUnload() {
			uni.$off('chooseAddress')
		},
		computed: {
			total_amount:{
				cache:false,
				get() {
					var total_amount = 0
					if(Object.keys(this.goods).length>0){
						total_amount += this.goods.goods_num * this.goods.goods_price
					}
					return (total_amount + this.goods.freight).toFixed(2)
				}
			}
		}
	}
</script>

<style lang="scss" scoped>
	@import "static/css/order.scss";
	.container {
		height: 100%;
		position: relative;
		.scroll{
			height: calc(100% - #{$bottom-h});
			.cart-container{
				padding: 20rpx 30rpx 0 30rpx;
				position: relative;
				&::before{
					content: '';
					position: absolute;
					left: 0;
					top: 0;
					width: 100%;
					height: 150rpx;
					background: $theme-color;
					z-index: 0;
				}
				.confirm-address,.goods-items{
					position: relative;
					z-index: 1;
				}
			}
		}
	}
</style>